// Cache Strategy: Spatial Locality (C-style)
// Data in main memory (RAM) is brought into cache in blocks (lines).
#define SIZE 1024
int matrix[SIZE][SIZE];
volatile long sum = 0;

// Good spatial locality: Accessing adjacent memory (Row-major)
// High Cache Hit Rate
for (int i=0; i<SIZE; i++)
    for (int j=0; j<SIZE; j++)
        sum += matrix[i][j];

// Poor spatial locality: Large stride access (Column-major)
// Low Cache Hit Rate (Thrashing)
for (int j=0; j<SIZE; j++)
    for (int i=0; i<SIZE; i++)
        sum += matrix[i][j];

// Optimization: Loop Interchange for speed tradeoff control
// (Compilers often optimize this, but explicit code is clearer)
